450	impl PropType {
451	    fn to_tagged_value(&self) -> serde_json::Value {
452	        match self {
453	            // Unit variants (primitives)
454	            PropType::String => serde_json::json!({"kind": "string"}),
455	            PropType::Number => serde_json::json!({"kind": "number"}),
456	            PropType::Boolean => serde_json::json!({"kind": "boolean"}),
457	            PropType::Null => serde_json::json!({"kind": "null"}),
458	            PropType::Undefined => serde_json::json!({"kind": "undefined"}),
459	            PropType::Any => serde_json::json!({"kind": "any"}),
460	            PropType::Never => serde_json::json!({"kind": "never"}),
461	            PropType::Unknown => serde_json::json!({"kind": "unknown"}),
462	            PropType::Void => serde_json::json!({"kind": "void"}),
463	            PropType::ReactNode => serde_json::json!({"kind": "reactNode"}),
464	            PropType::CssProperties => serde_json::json!({"kind": "cssProperties"}),
465	            PropType::ElementType => serde_json::json!({"kind": "elementType"}),
466	            PropType::SxProps => serde_json::json!({"kind": "sxProps"}),
467	            // Newtype/tuple variants — give each a real field name instead of a
468	            // positional "0" key, matching the struct-style variants below.
469	            PropType::StringLiteral(s) => serde_json::json!({"kind": "stringLiteral", "value": s}),
470	            PropType::NumberLiteral(n) => {
471	                // `serde_json::Number` cannot represent NaN/Infinity (they'd
472	                // silently become JSON `null`, then round-trip back as `0.0`
473	                // — see `from_tagged_value` below). Tag non-finite values as
474	                // strings instead so the read side can tell them apart from a
475	                // genuinely-absent value.
476	                let value = if n.is_finite() {
477	                    serde_json::json!(n)
478	                } else if n.is_nan() {
479	                    serde_json::json!("NaN")
480	                } else if *n > 0.0 {
481	                    serde_json::json!("Infinity")
482	                } else {
483	                    serde_json::json!("-Infinity")
484	                };
485	                serde_json::json!({"kind": "numberLiteral", "value": value})
486	            }
487	            PropType::BoolLiteral(b) => serde_json::json!({"kind": "boolLiteral", "value": b}),
488	            PropType::Union(members) => serde_json::json!({
489	                "kind": "union",
490	                "members": members.iter().map(|m| m.to_tagged_value()).collect::<Vec<_>>()
491	            }),
492	            PropType::Intersection(members) => serde_json::json!({
493	                "kind": "intersection",
494	                "members": members.iter().map(|m| m.to_tagged_value()).collect::<Vec<_>>()
495	            }),
496	            PropType::Array(inner) => serde_json::json!({
497	                "kind": "array",
498	                "element": inner.to_tagged_value()
499	            }),
500	            PropType::Tuple(members) => serde_json::json!({
501	                "kind": "tuple",
502	                "elements": members.iter().map(|m| m.to_tagged_value()).collect::<Vec<_>>()
503	            }),
504	            PropType::Object(fields) => serde_json::json!({
505	                "kind": "object",
506	                "fields": fields.iter().map(|f| serde_json::json!({
507	                    "name": f.name,
508	                    "propType": f.prop_type.to_tagged_value(),
509	                    "required": f.required,
510	                    "description": f.description,
511	                })).collect::<Vec<_>>()
512	            }),
513	            // Struct variants — fields merge directly with kind
514	            PropType::Named { name, args } => serde_json::json!({
515	                "kind": "named",
516	                "name": name.as_str(),
517	                "args": args.iter().map(|a| a.to_tagged_value()).collect::<Vec<_>>()
518	            }),
519	            PropType::EventHandler { event_type, param_name } => serde_json::json!({
520	                "kind": "eventHandler",
521	                "eventType": event_type,
522	                "paramName": param_name
523	            }),
524	            PropType::Ref { element } => serde_json::json!({
525	                "kind": "ref",
526	                "element": element
527	            }),
528	            PropType::HtmlAttributes { element, omitted } => serde_json::json!({
529	                "kind": "htmlAttributes",
530	                "element": element,
531	                "omitted": omitted
532	            }),
533	            PropType::LiteralUnion { members, has_default } => serde_json::json!({
534	                "kind": "literalUnion",
535	                "members": members,
536	                "hasDefault": has_default
537	            }),
538	            PropType::Opaque(OpaqueDetail { raw, reason }) => {
539	                let reason_val = match reason {
540	                    OpaqueReason::ConditionalType => serde_json::json!({"type": "conditionalType"}),
541	                    OpaqueReason::MappedType => serde_json::json!({"type": "mappedType"}),
542	                    OpaqueReason::ModuleAugmentation => {
543	                        serde_json::json!({"type": "moduleAugmentation"})
544	                    }
545	                    OpaqueReason::RuntimeDependent { function_name } => {
546	                        serde_json::json!({"type": "runtimeDependent", "functionName": function_name})
547	                    }
548	                    OpaqueReason::UnresolvableImport { specifier } => {
549	                        serde_json::json!({"type": "unresolvableImport", "specifier": specifier})
550	                    }
551	                    OpaqueReason::PandaCodegenMissing => {
552	                        serde_json::json!({"type": "pandaCodegenMissing"})
553	                    }
554	                    OpaqueReason::DepthExceeded => serde_json::json!({"type": "depthExceeded"}),
555	                    OpaqueReason::IndexedAccess { expression } => {
556	                        serde_json::json!({"type": "indexedAccess", "expression": expression})
557	                    }
558	                    OpaqueReason::TemplateLiteral { expression } => {
559	                        serde_json::json!({"type": "templateLiteral", "expression": expression})
560	                    }
561	                    OpaqueReason::MultiParamFunction => serde_json::json!({"type": "multiParamFunction"}),
562	                    OpaqueReason::UnsupportedExpression => {
563	                        serde_json::json!({"type": "unsupportedExpression"})
564	                    }
565	                };
566	                serde_json::json!({"kind": "opaque", "raw": raw, "reason": reason_val})
567	            }
568	        }
569	    }
