571	    fn from_tagged_value(v: &serde_json::Value) -> Result<Self, std::string::String> {
572	        let kind = v
573	            .get("kind")
574	            .and_then(|k| k.as_str())
575	            .ok_or_else(|| "missing 'kind' field in PropType JSON".to_string())?;
576	        match kind {
577	            "string" => Ok(PropType::String),
578	            "number" => Ok(PropType::Number),
579	            "boolean" => Ok(PropType::Boolean),
580	            "null" => Ok(PropType::Null),
581	            "undefined" => Ok(PropType::Undefined),
582	            "any" => Ok(PropType::Any),
583	            "never" => Ok(PropType::Never),
584	            "unknown" => Ok(PropType::Unknown),
585	            "void" => Ok(PropType::Void),
586	            "reactNode" | "react_node" => Ok(PropType::ReactNode),
587	            "cssProperties" | "css_properties" => Ok(PropType::CssProperties),
588	            "elementType" | "element_type" => Ok(PropType::ElementType),
589	            "sxProps" | "sx_props" => Ok(PropType::SxProps),
590	            "stringLiteral" | "string_literal" => {
591	                let s = v["value"].as_str().unwrap_or("").to_owned();
592	                Ok(PropType::StringLiteral(s))
593	            }
594	            "numberLiteral" | "number_literal" => {
595	                let n = match v.get("value") {
596	                    Some(val) if val.is_string() => match val.as_str().unwrap_or("") {
597	                        "NaN" => f64::NAN,
598	                        "Infinity" => f64::INFINITY,
599	                        "-Infinity" => f64::NEG_INFINITY,
600	                        _ => 0.0,
601	                    },
602	                    Some(val) => val.as_f64().unwrap_or(0.0),
603	                    None => 0.0,
604	                };
605	                Ok(PropType::NumberLiteral(n))
606	            }
607	            "boolLiteral" | "bool_literal" => {
608	                let b = v["value"].as_bool().unwrap_or(false);
609	                Ok(PropType::BoolLiteral(b))
610	            }
611	            "union" => {
612	                let members = v["members"]
613	                    .as_array()
614	                    .map(|a| a.iter().map(Self::from_tagged_value).collect::<Result<Vec<_>, _>>())
615	                    .unwrap_or(Ok(vec![]))?;
616	                Ok(PropType::Union(members))
617	            }
618	            "intersection" => {
619	                let members = v["members"]
620	                    .as_array()
621	                    .map(|a| a.iter().map(Self::from_tagged_value).collect::<Result<Vec<_>, _>>())
622	                    .unwrap_or(Ok(vec![]))?;
623	                Ok(PropType::Intersection(members))
624	            }
625	            "array" => {
626	                let inner = Self::from_tagged_value(&v["element"])?;
627	                Ok(PropType::Array(Box::new(inner)))
628	            }
629	            "tuple" => {
630	                let members = v["elements"]
631	                    .as_array()
632	                    .map(|a| a.iter().map(Self::from_tagged_value).collect::<Result<Vec<_>, _>>())
633	                    .unwrap_or(Ok(vec![]))?;
634	                Ok(PropType::Tuple(members))
635	            }
636	            "object" => {
637	                let fields = v["fields"]
638	                    .as_array()
639	                    .map(|a| {
640	                        a.iter()
641	                            .map(|f| {
642	                                Ok(ObjectField {
643	                                    name: f["name"].as_str().unwrap_or("").to_owned(),
644	                                    prop_type: Self::from_tagged_value(&f["propType"])?,
645	                                    required: f["required"].as_bool().unwrap_or(false),
646	                                    description: f["description"].as_str().unwrap_or("").to_owned(),
647	                                })
648	                            })
649	                            .collect::<Result<Vec<_>, std::string::String>>()
650	                    })
651	                    .unwrap_or(Ok(vec![]))?;
652	                Ok(PropType::Object(fields))
653	            }
654	            "named" => {
655	                let name = v["name"].as_str().unwrap_or("").into();
656	                let args = v["args"]
657	                    .as_array()
658	                    .map(|a| a.iter().map(Self::from_tagged_value).collect::<Result<Vec<_>, _>>())
659	                    .unwrap_or(Ok(vec![]))?;
660	                Ok(PropType::Named { name, args })
661	            }
662	            "eventHandler" | "event_handler" => {
663	                let event_type = v["eventType"].as_str().or_else(|| v["event_type"].as_str()).unwrap_or("").to_owned();
664	                let param_name = v["paramName"].as_str().or_else(|| v["param_name"].as_str()).map(|s| s.to_owned());
665	                Ok(PropType::EventHandler { event_type, param_name })
666	            }
667	            "ref" => {
668	                let element = v["element"].as_str().map(|s| s.to_owned());
669	                Ok(PropType::Ref { element })
670	            }
671	            "htmlAttributes" | "html_attributes" => {
672	                let element = v["element"].as_str().unwrap_or("div").to_owned();
673	                let omitted = v["omitted"]
674	                    .as_array()
675	                    .map(|a| a.iter().filter_map(|v| v.as_str()).map(|s| s.to_owned()).collect())
676	                    .unwrap_or_default();
677	                Ok(PropType::HtmlAttributes { element, omitted })
678	            }
679	            "literalUnion" | "literal_union" => {
680	                let members = v["members"]
681	                    .as_array()
682	                    .map(|a| a.iter().filter_map(|v| v.as_str()).map(|s| s.to_owned()).collect())
683	                    .unwrap_or_default();
684	                let has_default = v["hasDefault"].as_bool().or_else(|| v["has_default"].as_bool()).unwrap_or(false);
685	                Ok(PropType::LiteralUnion { members, has_default })
686	            }
687	            "opaque" => {
688	                let raw = v["raw"].as_str().unwrap_or("").to_owned();
689	                let reason = match v["reason"]["type"].as_str().unwrap_or("depthExceeded") {
690	                    "conditionalType" => OpaqueReason::ConditionalType,
691	                    "mappedType" => OpaqueReason::MappedType,
692	                    "moduleAugmentation" => OpaqueReason::ModuleAugmentation,
693	                    "runtimeDependent" => OpaqueReason::RuntimeDependent {
694	                        function_name: v["reason"]["functionName"].as_str().unwrap_or("").to_owned(),
695	                    },
696	                    "unresolvableImport" => OpaqueReason::UnresolvableImport {
697	                        specifier: v["reason"]["specifier"].as_str().unwrap_or("").to_owned(),
698	                    },
699	                    "pandaCodegenMissing" => OpaqueReason::PandaCodegenMissing,
700	                    "indexedAccess" => OpaqueReason::IndexedAccess {
701	                        expression: v["reason"]["expression"].as_str().unwrap_or("").to_owned(),
702	                    },
703	                    "templateLiteral" => OpaqueReason::TemplateLiteral {
704	                        expression: v["reason"]["expression"].as_str().unwrap_or("").to_owned(),
705	                    },
706	                    "multiParamFunction" => OpaqueReason::MultiParamFunction,
707	                    "unsupportedExpression" => OpaqueReason::UnsupportedExpression,
708	                    _ => OpaqueReason::DepthExceeded,
709	                };
710	                Ok(OpaqueDetail::new(raw, reason))
711	            }
712	            other => Ok(OpaqueDetail::new(format!("unknown PropType kind: {}", other), OpaqueReason::DepthExceeded)),
713	        }
714	    }
715	}
