732	/// Whether `name` can appear bare as an object-type field key in TypeScript
733	/// source (`{ name: T }`) or must be quoted (`{ 'name': T }`) — e.g. CSS custom
734	/// property names (`--accent`) and dashed HTML attributes (`data-testid`).
735	fn is_valid_identifier(name: &str) -> bool {
736	    let mut chars = name.chars();
737	    let Some(first) = chars.next() else { return false };
738	    (first.is_alphabetic() || first == '_' || first == '$')
739	        && chars.all(|c| c.is_alphanumeric() || c == '_' || c == '$')
740	}
