742	/// Why a type could not be resolved.
743	#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
744	#[serde(rename_all = "camelCase")]
745	pub enum OpaqueReason {
746	    /// TypeScript conditional type — needs type checker
747	    ConditionalType,
748	    /// TypeScript mapped type — needs type checker
749	    MappedType,
750	    /// Module augmentation result — needs type checker
751	    ModuleAugmentation,
752	    /// Runtime-dependent: cva(), tv(), etc. where args not statically visible
753	    RuntimeDependent { function_name: std::string::String },
754	    /// Import could not be resolved to a file
755	    UnresolvableImport { specifier: std::string::String },
756	    /// PandaCSS styled-system not generated yet
757	    PandaCodegenMissing,
758	    /// Maximum resolution depth exceeded (circular or too deep)
759	    DepthExceeded,
760	    /// Indexed access type (Type["key"]) — enable typescript-go to resolve.
761	    IndexedAccess { expression: std::string::String },
762	    /// Template literal type — partially or fully unresolvable.
763	    TemplateLiteral { expression: std::string::String },
764	    /// A function type with more than one parameter — describing it fully
765	    /// needs a real type signature, not just an EventHandler-shaped summary.
766	    MultiParamFunction,
767	    /// A raw type expression the extractor couldn't parse into any recognized
768	    /// structural shape (not a depth or circularity problem — see
769	    /// DepthExceeded for that).
770	    UnsupportedExpression,
771	}
