1	//! Prop-type resolver — Phase 3a.
2	//!
3	//! Converts `ComponentMapping` (raw collected data) into a fully resolved
4	//! `ComponentEntry` with `PropType` props.
5	//!
6	//! Central design:
7	//! - `resolve_component` is the entry point (called in parallel per component).
8	//! - `resolve_collected_type` is the recursive dispatch for `CollectedType → PropType`.
9	//! - No string parsing happens here — everything is already structured `CollectedType`.
10	//! - Graceful degradation: every unresolvable type becomes `PropType::Opaque` + a `Diagnostic`.
11	
12	use std::collections::BTreeMap;
13	use std::sync::Arc;
14	
15	#[allow(unused_imports)]
16	use camino::{Utf8Path, Utf8PathBuf};
17	use compact_str::CompactString;
18	use oxc_resolver::{AliasValue, ResolveOptions, Resolver};
19	use rustc_hash::{FxHashMap, FxHashSet};
20	
21	use crate::import_map::ImportResolutionMap;
22	use crate::pipeline::PipelineOptions;
23	use crate::react_types;
24	use crate::types::*;
25	
26	mod alias;
27	mod chain;
28	mod collected;
29	mod extends;
30	mod func;
31	mod html;
32	mod import;
33	mod named;
34	mod precedence;
35	mod primitives;
36	mod react;
37	mod substitute;
38	mod template;
39	
40	#[cfg(test)]
41	pub(crate) use import::{follow_reexports_call_count, reset_follow_reexports_call_count};
42	
43	// ─── Constants ────────────────────────────────────────────────────────────────
44	
45	/// Maximum recursion depth for type resolution.
46	/// Prevents infinite loops on circular type references.
47	const MAX_DEPTH: u8 = 20;
48	
49	/// Shared "max resolution depth exceeded" diagnostic — every recursive
50	/// resolver entry point (resolve_named, resolve_props_chain,
51	/// resolve_collected_type) hits this same guard, and previously each built
52	/// its own slightly different message with only one of the three including
53	/// the circular-reference hint. `what` should read naturally after
54	/// "resolving", e.g. "type 'Foo'" or "named type 'Bar'".
55	pub(super) fn max_depth_diagnostic(what: &str, file: &Utf8Path) -> Diagnostic {
56	    Diagnostic {
57	        severity: DiagnosticSeverity::Warning,
58	        message: format!("Max resolution depth exceeded resolving {what}"),
59	        file: Some(file.to_string()),
60	        line: None,
61	        column: None,
62	        help: Some("This may indicate a circular type reference.".into()),
63	        code: DiagnosticCode::MaxDepthExceeded,
64	    }
65	}
66	
67	/// Import resolution may have redirected a name to a different name/file
68	/// (re-exports, barrel files) — surface that resolved location in an
69	/// "unresolvable type" diagnostic when it differs from the naive
70	/// name/consuming-file, since "Cannot resolve X in file A" is confusing if X
71	/// actually lives in file B. Returns an empty string when nothing to add.
72	pub(super) fn unresolved_location_note(
73	    original_name: &str,
74	    consuming_file: &Utf8Path,
75	    canonical_file: &Utf8Path,
76	    canonical_name: &str,
77	) -> String {
78	    let resolved_elsewhere = canonical_file != consuming_file || canonical_name != original_name;
79	    if resolved_elsewhere {
80	        format!(" (resolved to '{canonical_name}' in '{canonical_file}')")
81	    } else {
82	        String::new()
83	    }
84	}
85	
86	/// TypeScript's own generic utility types — never prop providers, and expanding
87	/// them structurally needs a type checker we don't have. `Omit`/`Pick`/`Partial`/
88	/// `Readonly` get real structural handling as alias shapes (see resolver/alias.rs);
89	/// this list exists so every OTHER arity/usage of these names (and the ones with
90	/// no structural handling at all) degrades to a silent no-op instead of a
91	/// spurious "cannot resolve" warning. Shared by chain.rs (props level) and
92	/// named.rs (type level) — previously duplicated as two independently-maintained
93	/// name lists that happened to agree, with no guard against them drifting apart.
94	pub(super) fn is_ts_utility_type(name: &str) -> bool {
95	    matches!(
96	        name,
97	        "Omit"
98	            | "Pick"
99	            | "Partial"
100	            | "Required"
101	            | "Readonly"
102	            | "NonNullable"
103	            | "ReturnType"
104	            | "Parameters"
105	            | "Awaited"
106	            | "Extract"
107	            | "Exclude"
108	            | "Record"
109	            | "ReadonlyArray"
110	            | "Array"
111	            | "Promise"
112	    )
113	}
114	
115	// ─── ResolutionContext ────────────────────────────────────────────────────────
116	
117	/// Shared, read-only context passed to all resolution functions.
118	/// Arc'd so it can be cheaply shared across rayon threads.
119	pub struct ResolutionContext {
120	    pub global: Arc<GlobalSourceData>,
121	    pub import_map: Arc<ImportResolutionMap>,
122	    /// Fast `(file, name)` index over `global.interfaces`/`type_aliases` and
123	    /// their declared generic type parameters — see `named_type_index.rs`'s
124	    /// module doc for why this exists alongside (not instead of) those flat
125	    /// maps.
126	    pub(crate) named_types: Arc<crate::named_type_index::NamedTypeIndex>,
127	    pub oxc_resolver: Arc<Resolver>,
128	    pub extra_builtins: FxHashSet<CompactString>,
129	    /// Bare name → full scoped key ("file:name") index over `global.enums`,
130	    /// built once per resolution pass so `resolve_typeof` and
131	    /// `resolve_cva_variant_props` (VariantProps<typeof X>) can do an O(1)
132	    /// lookup instead of a linear scan with a `format!()` allocation per
133	    /// candidate on every reference. Ambiguous bare names (same name in two
134	    /// files) resolve to whichever key `global.enums` yields first during
135	    /// this build pass — the same tie-break the old linear scan produced,
136	    /// since both iterate the same underlying map.
137	    pub enum_bare_index: FxHashMap<CompactString, CompactString>,
138	    /// Same as `enum_bare_index`, but over `global.const_arrays` — for
139	    /// `(typeof X)[number]` on a flat `const X = [...] as const` array.
140	    pub const_array_bare_index: FxHashMap<CompactString, CompactString>,
141	    /// How much of an inherited HTML element's attributes to expose.
142	    pub html_attributes: crate::pipeline::HtmlAttributeMode,
143	    /// Paths to TypeScript's own `lib.es5.d.ts`/`lib.dom.d.ts`, if resolvable
144	    /// from this project (empty otherwise — see `resolve_ts_lib_paths`).
145	    /// Checked as a last-resort fallback when a bare, never-imported name
146	    /// (a real native/DOM global like `Date`) doesn't resolve via the normal
147	    /// same-file lookup — see `import::lookup_interface`/`lookup_type_alias`.
148	    pub ambient_global_files: Vec<Utf8PathBuf>,
149	}
150	
151	impl ResolutionContext {
152	    pub fn new(global: Arc<GlobalSourceData>, options: &PipelineOptions) -> Self {
153	        let named_types = Arc::new(crate::named_type_index::NamedTypeIndex::build(&global));
154	        Self::build(global, options, compute_ambient_global_files(options), named_types)
155	    }
156	
157	    /// Same as `new`, but for a caller that already knows the answer to
158	    /// `compute_ambient_global_files` (skips its filesystem walk — see
159	    /// `WatchSession::update_file`) and already maintains its own
160	    /// incrementally-patched `NamedTypeIndex` rather than wanting one freshly
161	    /// rebuilt from the whole (possibly large) merged `global` on every call.
162	    /// A full rebuild here is proportionate for `new`'s one-shot, resolve-
163	    /// every-component-in-the-project caller, which amortizes it across many
164	    /// lookups — but `WatchSession::update_file` runs once per file save and
165	    /// typically re-resolves only the handful of components a single edit
166	    /// actually affects, so paying a whole-project index rebuild on every
167	    /// keystroke-adjacent save measurably regressed watch-mode latency (see
168	    /// `NamedTypeIndex::remove_file`'s doc comment).
169	    pub fn new_with_cached_ambient_global_files(
170	        global: Arc<GlobalSourceData>,
171	        options: &PipelineOptions,
172	        ambient_global_files: Vec<Utf8PathBuf>,
173	        named_types: Arc<crate::named_type_index::NamedTypeIndex>,
174	    ) -> Self {
175	        Self::build(global, options, ambient_global_files, named_types)
176	    }
177	
178	    fn build(
179	        global: Arc<GlobalSourceData>,
180	        options: &PipelineOptions,
181	        ambient_global_files: Vec<Utf8PathBuf>,
182	        named_types: Arc<crate::named_type_index::NamedTypeIndex>,
183	    ) -> Self {
184	        let alias: Vec<(String, Vec<AliasValue>)> = react::read_tsconfig_paths(options.tsconfig_path.as_deref());
185	
186	        let resolve_options = ResolveOptions {
187	            condition_names: vec!["types".into(), "import".into(), "require".into(), "default".into()],
188	            main_fields: vec!["types".into(), "typings".into(), "module".into(), "main".into()],
189	            extensions: vec![".ts".into(), ".tsx".into(), ".d.ts".into(), ".js".into()],
190	            alias,
191	            ..ResolveOptions::default()
192	        };
193	
194	        let mut enum_bare_index: FxHashMap<CompactString, CompactString> = FxHashMap::default();
195	        for key in global.enums.keys() {
196	            let bare = key.rsplit_once(':').map(|(_, name)| name).unwrap_or(key.as_str());
197	            enum_bare_index.entry(CompactString::from(bare)).or_insert_with(|| CompactString::from(key.as_str()));
198	        }
199	
200	        let mut const_array_bare_index: FxHashMap<CompactString, CompactString> = FxHashMap::default();
201	        for key in global.const_arrays.keys() {
202	            let bare = key.rsplit_once(':').map(|(_, name)| name).unwrap_or(key.as_str());
203	            const_array_bare_index
204	                .entry(CompactString::from(bare))
205	                .or_insert_with(|| CompactString::from(key.as_str()));
206	        }
207	
208	        Self {
209	            import_map: Arc::new(ImportResolutionMap::build(&global)),
210	            named_types,
211	            global,
212	            oxc_resolver: Arc::new(Resolver::new(resolve_options)),
213	            extra_builtins: options.extra_builtins.clone(),
214	            enum_bare_index,
215	            const_array_bare_index,
216	            html_attributes: options.html_attributes,
217	            ambient_global_files,
218	        }
219	    }
220	}
221	
222	/// Resolve TypeScript's own `lib.es5.d.ts`/`lib.dom.d.ts` paths for the given
223	/// options' first source directory, if resolvable — see `resolve_ts_lib_paths`.
224	pub fn compute_ambient_global_files(options: &PipelineOptions) -> Vec<Utf8PathBuf> {
225	    options
226	        .src_dirs
227	        .first()
228	        .and_then(|dir| std::fs::canonicalize(dir).ok())
229	        .and_then(|p| Utf8PathBuf::from_path_buf(p).ok())
230	        .map(|from_dir| resolve_ts_lib_paths(&from_dir).into_iter().map(Utf8PathBuf::from).collect())
231	        .unwrap_or_default()
232	}
233	
234	/// Resolve `package_name` (e.g. "react") to its real `.d.ts` file path, for
235	/// callers outside the resolver — the pipeline's `HtmlAttributeMode::Full`
236	/// wiring needs this to know which file to parse and merge, before a
237	/// `ResolutionContext` (which needs the already-merged `GlobalSourceData`) can
238	/// exist yet.
239	pub fn resolve_package_dts_path(from_dir: &camino::Utf8Path, package_name: &str) -> Option<String> {
240	    let resolve_options = ResolveOptions {
241	        condition_names: vec!["types".into(), "import".into(), "require".into(), "default".into()],
242	        main_fields: vec!["types".into(), "typings".into(), "module".into(), "main".into()],
243	        extensions: vec![".ts".into(), ".tsx".into(), ".d.ts".into(), ".js".into()],
244	        ..ResolveOptions::default()
245	    };
246	    let resolver = Resolver::new(resolve_options);
247	    react::resolve_package_types_file(&resolver, from_dir, package_name)
248	}
249	
250	/// Resolve TypeScript's own `lib.es5.d.ts`/`lib.dom.d.ts` — the files that
251	/// declare native/DOM ambient globals (`Date`, `RegExp`, `Element`, `Node`, …).
252	/// These never go through an import (they're ambient scripts, not modules),
253	/// so nothing else ever has a reason to locate them the way an import
254	/// statement triggers `@types/react` resolution. Returns whichever of the two
255	/// are actually found — an empty `Vec` when the `typescript` package isn't
256	/// reachable from `from_dir` at all (e.g. no real project), which is a
257	/// legitimate, silent degradation, not an error.
258	pub fn resolve_ts_lib_paths(from_dir: &camino::Utf8Path) -> Vec<String> {
259	    let resolve_options = ResolveOptions { extensions: vec![".d.ts".into()], ..ResolveOptions::default() };
260	    let resolver = Resolver::new(resolve_options);
261	    ["lib.es5.d.ts", "lib.dom.d.ts"]
262	        .into_iter()
263	        .filter_map(|lib_file| {
264	            let specifier = format!("typescript/lib/{lib_file}");
265	            resolver.resolve(from_dir.as_std_path(), &specifier).ok().map(|r| r.path().to_string_lossy().into_owned())
266	        })
267	        .collect()
268	}
269	
270	// ─── Entry Point ─────────────────────────────────────────────────────────────
271	
272	/// Resolve a `ComponentMapping` to a complete `ComponentEntry`.
273	///
274	/// Called in parallel via rayon — must be `Send + Sync` (all data is owned/Arc'd).
275	pub fn resolve_component(mapping: &ComponentMapping, ctx: &ResolutionContext) -> (ComponentEntry, Vec<Diagnostic>) {
276	    let mut state = ResolveState::default();
277	
278	    let chain = chain::resolve_props_chain(
279	        mapping.props_type_name.as_str(),
280	        &mapping.props_type_args,
281	        &mapping.file_path,
282	        mapping,
283	        ctx,
284	        &mut state,
285	        0,
286	    );
287	
288	    // Build props BTreeMap — own props win over inherited props with same name.
289	    let mut props: BTreeMap<String, ParsedProp> = BTreeMap::new();
290	    for prop in chain.props {
291	        props.entry(prop.name.clone()).or_insert(prop);
292	    }
293	
294	    // Populate notable_inherited from HTML element layers and non-HTML inherited layers.
295	    let mut notable_inherited: BTreeMap<String, ParsedProp> = BTreeMap::new();
296	    for layer in &chain.inheritance {
297	        if let Some(ref element) = layer.html_element {
298	            // Curated-mode synthesis only: Full mode already merged the real
299	            // attributes directly into `props` (see resolver/extends.rs); None
300	            // mode wants no HTML attrs synthesized at all.
301	            if ctx.html_attributes != crate::pipeline::HtmlAttributeMode::Curated {
302	                continue;
303	            }
304	            let notable_attrs = react_types::notable_html_attrs(element);
305	            for attr_name in notable_attrs {
306	                if props.contains_key(*attr_name) {
307	                    continue;
308	                } // own prop wins
309	                if notable_inherited.contains_key(*attr_name) {
310	                    continue;
311	                } // already added
312	
313	                // Synthesize a minimal prop for display purposes
314	                let prop_type = html::infer_html_attr_prop_type(attr_name);
315	                notable_inherited.insert(
316	                    attr_name.to_string(),
317	                    ParsedProp::new(
318	                        attr_name.to_string(),
319	                        prop_type,
320	                        false,
321	                        None,
322	                        String::new(),
323	                        Default::default(),
324	                        Some(PropParent {
325	                            name: format!("{}HTMLAttributes", html::capitalize_element(element)),
326	                            file_name: "node_modules/@types/react/index.d.ts".to_string(),
327	                        }),
328	                        vec![],
329	                    ),
330	                );
331	            }
332	        } else {
333	            // For non-HTML layers: add inherited props from chain.inherited_by_name
334	            for (name, prop) in &chain.inherited_by_name {
335	                if !props.contains_key(name) && !notable_inherited.contains_key(name) {
336	                    notable_inherited.insert(name.clone(), prop.clone());
337	                }
338	            }
339	        }
340	    }
341	
342	    // Detect discriminated union if applicable.
343	    let discriminant_prop = chain.discriminant_prop;
344	
345	    (
346	        ComponentEntry {
347	            display_name: mapping.component_name.clone(),
348	            file_path: mapping.file_path.clone(),
349	            description: mapping.description.clone(),
350	            props,
351	            inheritance: chain.inheritance,
352	            notable_inherited,
353	            discriminant_prop,
354	            composes: chain.composes,
355	            tags: mapping.tags.clone(),
356	            methods: vec![],
357	        },
358	        state.diagnostics,
359	    )
360	}
361	
362	// ─── Intermediate Resolution Result ──────────────────────────────────────────
363	
364	/// Result of resolving a props chain (including extends).
365	struct ResolvedChain {
366	    /// Resolved props (may include inherited props).
367	    props: Vec<ParsedProp>,
368	    /// Inheritance layers, outermost first.
369	    inheritance: Vec<InheritedLayer>,
370	    /// Inherited props keyed by name — for notable_inherited population.
371	    inherited_by_name: FxHashMap<String, ParsedProp>,
372	    /// Type names that could not be resolved.
373	    composes: Vec<String>,
374	    /// Discriminant prop name if this is a discriminated union.
375	    discriminant_prop: Option<String>,
376	}
377	
378	impl ResolvedChain {
379	    /// The base empty chain. Deliberately not `Default` — every accumulator
380	    /// site (`resolve_interface_chain`, `resolve_base_as_chain`, ...) that
381	    /// wants "start empty, then push into" calls this directly instead; the
382	    /// two *give-up* entry points (`empty_with_compose`, `give_up`) are the
383	    /// only public-facing "this type contributes nothing" signals. Visible to
384	    /// `chain`/`alias`/`extends` since they're child modules of `resolver`.
385	    fn empty() -> Self {
386	        Self {
387	            props: Vec::new(),
388	            inheritance: Vec::new(),
389	            inherited_by_name: FxHashMap::default(),
390	            composes: Vec::new(),
391	            discriminant_prop: None,
392	        }
393	    }
394	
395	    fn empty_with_compose(type_name: String) -> Self {
396	        Self { composes: vec![type_name], ..Self::empty() }
397	    }
398	
399	    /// Give up resolving `type_name` — record it in `composes` (same as
400	    /// `empty_with_compose`) and, if `diag` is given, push it onto `state`
401	    /// first. The sanctioned "give up" entry point for every "this type
402	    /// couldn't be followed further, stop here" path. Replaces the bare
403	    /// `ResolvedChain::default()` the cycle-detected branch used to return,
404	    /// which let that one give-up site skip explaining why.
405	    fn give_up(type_name: String, diag: Option<Diagnostic>, state: &mut ResolveState) -> Self {
406	        if let Some(d) = diag {
407	            state.diagnostics.push(d);
408	        }
409	        Self::empty_with_compose(type_name)
410	    }
411	
412	    /// Merge a parent chain into self — own props already in `self.props` take priority.
413	    fn merge_parent(&mut self, parent: ResolvedChain) {
414	        // Collect existing prop names so we can skip duplicates.
415	        let existing: FxHashSet<String> = self.props.iter().map(|p| p.name.clone()).collect();
416	
417	        for prop in parent.props {
418	            if !existing.contains(&prop.name) {
419	                self.props.push(prop.clone());
420	            }
421	            // Always populate inherited_by_name so notable lookup works.
422	            self.inherited_by_name.entry(prop.name.clone()).or_insert(prop);
423	        }
424	
425	        // Prepend parent inheritance layers (parent is further up the chain).
426	        let mut new_inheritance = parent.inheritance;
427	        new_inheritance.append(&mut self.inheritance);
428	        self.inheritance = new_inheritance;
429	
430	        self.composes.extend(parent.composes);
431	        for (name, prop) in parent.inherited_by_name {
432	            self.inherited_by_name.entry(name).or_insert(prop);
433	        }
434	
435	        // A discriminated union nested inside an intersection (e.g. `Base & (A | B)`)
436	        // surfaces its discriminant on the union member's own chain — propagate it
437	        // up rather than silently dropping it in favor of the fresh, empty chain
438	        // being merged into.
439	        if self.discriminant_prop.is_none() {
440	            self.discriminant_prop = parent.discriminant_prop;
441	        }
442	    }
443	}
444	
