41	/// Stateful session for incremental watch-mode extraction.
42	///
43	/// `global`, `reverse_deps`, and `component_cache` are updated atomically /
44	/// concurrently on each file change. `reverse_deps` is rebuilt in full on
45	/// structural changes (new file, deleted file) via a new `WatchSession` — it
46	/// does not track incremental import-graph edits within a session.
47	pub struct WatchSession {
48	    pub options: PipelineOptions,
49	    /// Current merged source data — swapped atomically via `ArcSwap`.
50	    pub global: ArcSwap<GlobalSourceData>,
51	    /// Reverse-dependency graph built at initialisation time — swapped
52	    /// atomically via `ArcSwap` so `initialize()` can populate it from the
53	    /// first fully-merged `global` (it doesn't exist yet at `new()`).
54	    pub reverse_deps: ArcSwap<ReverseDeps>,
55	    /// Per-file SourceData cache (avoids re-reading files that haven't changed).
56	    pub source_cache: DashMap<Utf8PathBuf, SourceData>,
57	    /// Latest resolved component entries, keyed by display name.
58	    pub component_cache: DashMap<String, ComponentEntry>,
59	    /// Latest diagnostics per file, replaced (not appended) on each re-update so a
60	    /// fixed file's stale diagnostics don't linger — mirrors GlobalSourceData::remove_file's
61	    /// per-file replacement semantics.
62	    pub diagnostics: DashMap<Utf8PathBuf, Vec<Diagnostic>>,
63	    /// TypeScript's own lib.d.ts paths, computed once here at `initialize()`
64	    /// rather than by every `ResolutionContext::new` inside `update_file` —
65	    /// `options.src_dirs` (the only input this depends on) never changes
66	    /// within a session, so re-walking the filesystem for it on every single
67	    /// file save would be pure waste.
68	    ambient_global_files: std::sync::OnceLock<Vec<Utf8PathBuf>>,
69	    /// Guards initialize() so concurrent callers don't race to build caches.
70	    initialized: Mutex<bool>,
71	    /// Fast `(file, name)` interface/type-alias index — mirrors `self.global`'s
72	    /// incremental per-file patching (`remove_file` + merge on each edit)
73	    /// rather than being rebuilt from the whole project on every
74	    /// `update_file` call. `Mutex<Arc<_>>` (not `ArcSwap`, unlike `global`):
75	    /// `update_file` mutates it in place via `Arc::make_mut` when nothing else
76	    /// still holds a reference (the common case — no full clone needed), and
77	    /// falls back to cloning only if a concurrent call is still using the
78	    /// previous snapshot. `ArcSwap::rcu` can't express "mutate in place when
79	    /// possible" — its closure always produces a brand new value.
80	    named_types: Mutex<Arc<crate::named_type_index::NamedTypeIndex>>,
81	}
82	
83	impl WatchSession {
84	    /// Create an empty WatchSession (call `initialize()` before first use).
85	    pub fn new(options: PipelineOptions) -> Self {
86	        Self {
87	            options,
88	            global: ArcSwap::new(Arc::new(GlobalSourceData::default())),
89	            reverse_deps: ArcSwap::new(Arc::new(ReverseDeps { inner: Default::default() })),
90	            source_cache: DashMap::new(),
91	            component_cache: DashMap::new(),
92	            diagnostics: DashMap::new(),
93	            ambient_global_files: std::sync::OnceLock::new(),
94	            initialized: Mutex::new(false),
95	            named_types: Mutex::new(Arc::new(crate::named_type_index::NamedTypeIndex::default())),
96	        }
97	    }
98	
99	    /// Run a full cold extraction to populate this session's caches.
100	    ///
101	    /// Idempotent — concurrent or repeated calls return the existing snapshot
102	    /// without re-running extraction.
103	    pub fn initialize(&self) -> ExtractionOutput {
104	        let mut guard = self.initialized.lock().unwrap_or_else(|poisoned| poisoned.into_inner());
105	        if *guard {
106	            return self.snapshot();
107	        }
108	
109	        // Single real pipeline run (discover, parse, merge, Full-mode
110	        // @types/react, ambient lib.d.ts, resolve) shared with the one-shot
111	        // extract() path — see extract_with_global's doc comment. Previously
112	        // this rebuilt GlobalSourceData by hand here, which skipped the
113	        // Full-mode/ambient-lib.d.ts merges entirely: the cold `output` below
114	        // was correct (it came from a real extract() call), but the `global`
115	        // this session persists for every subsequent update_file() was not.
116	        let (output, global, per_file_data) = super::extract_with_global(&self.options, true);
117	
118	        for (path, data) in per_file_data {
119	            self.source_cache.insert(path, data);
120	        }
121	
122	        let _ = self.ambient_global_files.set(crate::resolver::compute_ambient_global_files(&self.options));
123	        self.reverse_deps.store(Arc::new(ReverseDeps::build(&global)));
124	        *self.named_types.lock().unwrap_or_else(|p| p.into_inner()) =
125	            Arc::new(crate::named_type_index::NamedTypeIndex::build(&global));
126	        self.global.store(global);
127	
128	        // Seed component cache from the cold output.
129	        for (name, entry) in &output.components {
130	            self.component_cache.insert(name.clone(), entry.clone());
131	        }
132	
133	        *guard = true;
134	        output
135	    }
136	
137	    /// Return the current full extraction state from the in-memory caches.
138	    /// Suitable for writing to `--out` after each incremental update.
139	    pub fn snapshot(&self) -> ExtractionOutput {
140	        let components: std::collections::BTreeMap<String, ComponentEntry> =
141	            self.component_cache.iter().map(|r| (r.key().clone(), r.value().clone())).collect();
142	        let global = self.global.load();
143	        let enums: std::collections::BTreeMap<String, Vec<EnumEntry>> =
144	            global.enums.iter().map(|(k, v)| (k.clone(), v.clone())).collect();
145	
146	        // DashMap iteration order is arbitrary — sort by path for deterministic output.
147	        let mut by_path: Vec<(Utf8PathBuf, Vec<Diagnostic>)> =
148	            self.diagnostics.iter().map(|r| (r.key().clone(), r.value().clone())).collect();
149	        by_path.sort_by(|a, b| a.0.cmp(&b.0));
150	        let diagnostics: Vec<Diagnostic> = by_path.into_iter().flat_map(|(_, ds)| ds).collect();
151	
152	        // Only `components_extracted` is populated here — the other ExtractionStats
153	        // fields (files_parsed, dts_cache_hits, duration_ms, tier1/tier3/opaque
154	        // counts) describe a single extract() run's own bookkeeping, which this
155	        // session doesn't accumulate across incremental update_file() calls. A
156	        // consumer reading watch --out's stats block for anything but the
157	        // component count sees zeros — a known, narrower gap than reporting
158	        // componentsExtracted itself as 0 regardless of how many components exist.
159	        let stats = ExtractionStats { components_extracted: components.len() as u32, ..ExtractionStats::default() };
160	
161	        ExtractionOutput { components, enums, diagnostics, stats }
162	    }
163	
164	    /// Handle a single file change — re-resolve only affected components.
165	    pub fn update_file(&self, changed: &Utf8Path) -> IncrementalUpdate {
166	        let start = Instant::now();
167	
168	        // `discover_files`'s directory walk (via the `ignore` crate) resolves
169	        // symlinks in the paths it reports — e.g. macOS's `/var` -> `/private/var`
170	        // — so every path already stored in `global`/`reverse_deps` is in that
171	        // resolved form. A file-watcher-reported `changed` path is not
172	        // guaranteed to match unless it's canonicalized the same way; without
173	        // this, `reverse_deps.affected()` below would look up the wrong key and
174	        // silently find no dependents at all.
175	        let changed = canonicalize_best_effort(changed);
176	        let changed = changed.as_path();
177	
178	        // 1. Re-parse the changed file.
179	        let mut io_diagnostic: Option<Diagnostic> = None;
180	        let source = match std::fs::read_to_string(changed) {
181	            Ok(s) => s,
182	            Err(e) => {
183	                io_diagnostic = Some(Diagnostic::io_read_error(changed, &e));
184	                String::new()
185	            }
186	        };
187	        let new_data = crate::extractor::parse_file(changed, &source);
188	        self.source_cache.insert(changed.to_owned(), new_data.clone());
189	
190	        // 2. Patch GlobalSourceData atomically using rcu (read-copy-update).
191	        // rcu retries if the pointer was swapped by a concurrent update_file call,
192	        // preventing lost-update races under parallel file change events.
193	        // rcu's return value is the PRE-swap value (arc-swap's compare_and_swap
194	        // convention), not the value the closure just produced — the closure's
195	        // result must be re-read via load_full() to see the post-update state.
196	        self.global.rcu(|old| {
197	            let mut g = (**old).clone();
198	            g.remove_file(changed);
199	            g.merge(changed, new_data.clone());
200	            g
201	        });
202	        let new_global = self.global.load_full();
203	
204	        // Keep the named-type index in sync with `global`'s own unconditional
205	        // per-file patch above (same remove-then-merge shape, same lack of a
206	        // read-failure gate — this index derives from `global`, not from
207	        // `component_cache`'s separately-decided AC-019 persistence policy).
208	        // `Arc::make_mut` mutates in place when this call holds the only
209	        // reference (the common case), and clones only if a concurrent
210	        // `update_file` call is still using the previous snapshot.
211	        let named_types = {
212	            let mut guard = self.named_types.lock().unwrap_or_else(|p| p.into_inner());
213	            let index = Arc::make_mut(&mut guard);
214	            index.remove_file(changed);
215	            index.merge_file(&new_data);
216	            guard.clone()
217	        };
218	
219	        // 3. Find all transitively affected files via the reverse dep graph.
220	        let affected = self.reverse_deps.load().affected(changed);
221	
222	        // 4. Re-resolve affected components.
223	        // Borrowed, not cloned — same reasoning as the one-shot `extract()`
224	        // path's identical fix (pipeline/mod.rs): `resolve_component` already
225	        // takes `&ComponentMapping`, and `.par_iter()` below only ever
226	        // produces borrows anyway.
227	        let affected_mappings: Vec<&ComponentMapping> =
228	            new_global.component_mappings.iter().filter(|m| affected.contains(&m.file_path)).collect();
229	
230	        let ambient_global_files = self.ambient_global_files.get().cloned().unwrap_or_default();
231	        let ctx = ResolutionContext::new_with_cached_ambient_global_files(
232	            new_global.clone(),
233	            &self.options,
234	            ambient_global_files,
235	            named_types,
236	        );
237	        // Wrapped in `contain_panic` for the same reason as the one-shot `extract()`
238	        // path (pipeline/mod.rs) — one component's resolution panicking must degrade
239	        // to a per-component diagnostic instead of poisoning this `.collect()` and
240	        // losing every other affected component's re-resolution for this file change.
241	        let results: Vec<(ComponentEntry, Vec<Diagnostic>)> = affected_mappings
242	            .par_iter()
243	            .copied()
244	            .map(|m| {
245	                let label = format!("resolve:{}", m.component_name);
246	                crate::panic_guard::contain_panic(&label, || {
247	                    #[cfg(test)]
248	                    if m.component_name == super::RESOLVE_PANIC_TEST_SENTINEL {
249	                        panic!("simulated resolve-phase panic (test-only sentinel)");
250	                    }
251	
252	                    resolve_component(m, &ctx)
253	                })
254	                .unwrap_or_else(|diag| {
255	                    let stub = ComponentEntry {
256	                        display_name: m.component_name.clone(),
257	                        file_path: m.file_path.clone(),
258	                        description: String::new(),
259	                        props: Default::default(),
260	                        inheritance: vec![],
261	                        notable_inherited: Default::default(),
262	                        discriminant_prop: None,
263	                        composes: vec![],
264	                        tags: Default::default(),
265	                        methods: vec![],
266	                    };
267	                    (stub, vec![diag])
268	                })
269	            })
270	            .collect();
271	
272	        // A failed read (deletion, permission error, non-UTF8 content) must
273	        // NOT evict this file's cache entries — SPEC-PIPELINE-001's AC-019
274	        // deliberately specifies that a deleted file's previously-resolved
275	        // component stays in component_cache/snapshot() until a new
276	        // WatchSession is constructed, a documented (not accidental)
277	        // staleness gap distinct from the rename case below. Only a
278	        // successful re-read, which can genuinely produce a different set of
279	        // component names for this file, should evict what it no longer owns.
280	        let file_read_failed = io_diagnostic.is_some();
281	
282	        let mut updated_components = Vec::new();
283	        let mut diagnostics: Vec<Diagnostic> = io_diagnostic.into_iter().collect();
284	
285	        // Evict every existing component_cache entry that belonged to this
286	        // file — by whatever key it was stored under, bare or disambiguated —
287	        // before inserting its freshly-resolved entries. A bare `insert(
288	        // entry.display_name, ...)` here left two kinds of stale entries
289	        // behind forever: a renamed component's old-name key never got
290	        // removed, and a disambiguated key from initialize()'s cold Phase 5
291	        // pass was never touched by an update that only ever wrote the bare
292	        // key. Both traced to the same root cause — no eviction step existed
293	        // at all. This resolves the file's keys as a batch first so a
294	        // same-file rename doesn't race against its own insert below.
295	        if !file_read_failed {
296	            let stale_keys: Vec<String> = self
297	                .component_cache
298	                .iter()
299	                .filter(|r| r.value().file_path == changed)
300	                .map(|r| r.key().clone())
301	                .collect();
302	            for key in stale_keys {
303	                self.component_cache.remove(&key);
304	            }
305	        }
306	
307	        for (entry, diags) in results {
308	            // Disambiguate against whatever's left in the cache after this
309	            // file's own stale keys were just evicted above — mirrors Phase
310	            // 5's bare-then-disambiguated rule (extract()'s one-shot path),
311	            // checked incrementally instead of via a session-wide counter.
312	            // Deliberately narrower than Phase 5 in one respect: if a rename
313	            // elsewhere frees up a bare key another file's component was
314	            // disambiguated against earlier, that other entry stays under
315	            // its disambiguated key until its own file is next touched —
316	            // still correctly retrievable, just not repacked to the
317	            // now-available bare key. Re-optimizing every other cached
318	            // entry's key on every single-file edit would defeat the point
319	            // of incremental updates; only this file's own stale keys are
320	            // this method's responsibility.
321	            let key = if self.component_cache.iter().any(|r| r.value().display_name == entry.display_name) {
322	                format!("{} ({})", entry.display_name, entry.file_path)
323	            } else {
324	                entry.display_name.clone()
325	            };
326	            self.component_cache.insert(key, entry.clone());
327	            updated_components.push(entry);
328	            diagnostics.extend(diags);
329	        }
330	
331	        // Replace (not append) this file's diagnostics — a fixed file's prior
332	        // errors shouldn't linger in subsequent snapshots.
333	        if diagnostics.is_empty() {
334	            self.diagnostics.remove(changed);
335	        } else {
336	            self.diagnostics.insert(changed.to_owned(), diagnostics.clone());
337	        }
338	
339	        IncrementalUpdate {
340	            updated_components,
341	            affected_files: affected.into_iter().collect(),
342	            diagnostics,
343	            duration_ms: start.elapsed().as_millis() as u64,
344	        }
345	    }
346	}
