1	//! Extraction pipeline — Phase 3b.
2	//!
3	//! Orchestrates: file discovery → parallel parse → global merge → parallel resolve → output.
4	//! Also manages DTS cache and incremental watch-mode state.
5	
6	use std::collections::VecDeque;
7	use std::sync::atomic::{AtomicU32, Ordering};
8	use std::sync::Arc;
9	use std::time::Instant;
10	
11	use camino::{Utf8Path, Utf8PathBuf};
12	use rayon::prelude::*;
13	use rustc_hash::{FxHashMap, FxHashSet};
14	use serde::{Deserialize, Serialize};
15	
16	use crate::cache::DtsCache;
17	use crate::resolver::{resolve_component, ResolutionContext};
18	use crate::types::*;
19	
20	mod discover;
21	pub mod watch;
22	
23	use discover::{discover_files, should_skip};
24	pub use watch::WatchSession;
25	
26	/// Filename that trips a simulated panic in the Phase 2 parse closure —
27	/// exists only to let tests exercise `panic_guard::contain_panic`'s
28	/// containment without a plugin hook to inject a real one through.
29	#[cfg(test)]
30	const PARSE_PANIC_TEST_SENTINEL: &str = "__PANIC_TEST__.tsx";
31	
32	/// Component name that trips a simulated panic in the Phase 4 resolve
33	/// closure — same rationale as `PARSE_PANIC_TEST_SENTINEL`, but for
34	/// `resolve_component`, which can't be made to panic without editing
35	/// non-test resolver code. Must be PascalCase — `is_pascal_case` is how the
36	/// extractor decides a function declaration is a component in the first
37	/// place, so a non-PascalCase sentinel would never reach Phase 4 at all.
38	#[cfg(test)]
39	const RESOLVE_PANIC_TEST_SENTINEL: &str = "ResolvePanicTestSentinel";
40	
41	// ─── PipelineOptions ─────────────────────────────────────────────────────────
42	
43	/// User-supplied known type override for custom library patterns.
44	#[derive(Debug, Clone, Serialize, Deserialize)]
45	#[serde(tag = "kind", rename_all = "camelCase")]
46	pub enum KnownTypeOverride {
47	    Opaque { label: Option<String> },
48	    Alias { arg_index: usize },
49	    Skip,
50	}
51	
52	/// How much of an inherited HTML element's attribute surface to expose.
53	#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
54	#[serde(rename_all = "camelCase")]
55	pub enum HtmlAttributeMode {
56	    /// ~15-20 curated, commonly-documented attributes per element (onClick,
57	    /// disabled, aria-*, etc.) — the default. Matches RDT's shape for consumers
58	    /// that filter node_modules-sourced props, just with a smaller, hand-picked set.
59	    Curated,
60	    /// Actually resolve `@types/react`'s real `HTMLAttributes`/`AriaAttributes`/
61	    /// `DOMAttributes`/`<Element>HTMLAttributes` interface chain, matching RDT's
62	    /// full ~250-300 attributes per element.
63	    Full,
64	    /// Don't synthesize any inherited HTML attributes at all — own props only.
65	    None,
66	}
67	
68	/// Configuration for a single extraction run.
69	#[derive(Debug, Clone)]
70	pub struct PipelineOptions {
71	    /// Source directories to scan.
72	    pub src_dirs: Vec<Utf8PathBuf>,
73	    /// Extra glob-like patterns to exclude (on top of built-in: stories, tests, snapshots).
74	    pub exclude_patterns: Vec<String>,
75	    /// Component name prefixes to skip.
76	    pub exclude_prefixes: Vec<String>,
77	    /// React version — default: React 19.
78	    pub react_version: crate::react_types::ReactVersion,
79	    /// Whether to resolve cross-package types.
80	    pub cross_package: bool,
81	    /// PandaCSS generated output dir, if applicable.
82	    pub pandacss_outdir: Option<Utf8PathBuf>,
83	    /// Extra function names to treat as cva-like variant functions.
84	    pub variant_functions: Vec<String>,
85	    /// How much of an inherited HTML element's attributes to expose.
86	    pub html_attributes: HtmlAttributeMode,
87	    // ── Fields from architectural review ─────────────────────────────────────
88	    /// Path to tsconfig.json (auto-detected if None).
89	    pub tsconfig_path: Option<Utf8PathBuf>,
90	    /// Monorepo path aliases: package name → list of candidate root dirs.
91	    pub extra_paths: FxHashMap<String, Vec<Utf8PathBuf>>,
92	    /// User-supplied overrides for specific named types.
93	    pub known_type_overrides: FxHashMap<String, KnownTypeOverride>,
94	    /// Additional builtin type names beyond the React standard set.
95	    pub extra_builtins: FxHashSet<compact_str::CompactString>,
96	    /// Enable vanilla-extract CSS-in-JS support.
97	    pub vanilla_extract: bool,
98	    /// Cache directory. Defaults to `node_modules/.cache/oxc-react-docgen`.
99	    pub cache_dir: Option<Utf8PathBuf>,
100	    /// Future: opt-in to typescript-go for conditional/mapped type resolution.
101	    pub resolve_complex_types: bool,
102	    /// Custom docgen extension plugins.
103	    pub plugins: crate::plugin::PluginRegistry,
104	}
105	
106	impl Default for PipelineOptions {
107	    fn default() -> Self {
108	        Self {
109	            src_dirs: vec![Utf8PathBuf::from("./src")],
110	            exclude_patterns: vec![],
111	            exclude_prefixes: vec![],
112	            react_version: crate::react_types::REACT_19,
113	            cross_package: true,
114	            pandacss_outdir: None,
115	            variant_functions: vec!["cva".into(), "tv".into(), "defineRecipe".into(), "recipe".into()],
116	            html_attributes: HtmlAttributeMode::Curated,
117	            tsconfig_path: None,
118	            extra_paths: Default::default(),
119	            known_type_overrides: Default::default(),
120	            extra_builtins: Default::default(),
121	            vanilla_extract: false,
122	            cache_dir: None,
123	            resolve_complex_types: false,
124	            plugins: crate::plugin::PluginRegistry::default(),
125	        }
126	    }
127	}
128	
129	// ─── Incremental watch types ──────────────────────────────────────────────────
130	
131	/// Result of processing a single file change in watch mode.
132	#[derive(Serialize)]
133	#[serde(rename_all = "camelCase")]
134	pub struct IncrementalUpdate {
135	    pub updated_components: Vec<ComponentEntry>,
136	    pub affected_files: Vec<Utf8PathBuf>,
137	    pub diagnostics: Vec<Diagnostic>,
138	    pub duration_ms: u64,
139	}
140	
141	/// Reverse dependency graph: file → list of files that import from it.
142	/// Built once from GlobalSourceData; used by WatchSession for BFS propagation.
143	pub struct ReverseDeps {
144	    pub(super) inner: FxHashMap<Utf8PathBuf, Vec<Utf8PathBuf>>,
145	}
146	
147	impl ReverseDeps {
148	    /// Build from a fully-merged GlobalSourceData.
149	    pub fn build(global: &GlobalSourceData) -> Self {
150	        let mut inner: FxHashMap<Utf8PathBuf, Vec<Utf8PathBuf>> = Default::default();
151	
152	        for (consumer_file, imports) in &global.import_map {
153	            for import in imports {
154	                // Only chase relative imports — package imports can't be naively reversed.
155	                if import.specifier.starts_with('.') {
156	                    if let Some(parent) = consumer_file.parent() {
157	                        let target = parent.join(&import.specifier);
158	                        // Approximate extension normalization without I/O.
159	                        for ext in &[".ts", ".tsx", "/index.ts", "/index.tsx"] {
160	                            let candidate = Utf8PathBuf::from(format!("{}{}", target, ext));
161	                            inner.entry(candidate).or_default().push(consumer_file.clone());
162	                        }
163	                    }
164	                }
165	            }
166	        }
167	
168	        Self { inner }
169	    }
170	
171	    /// BFS: collect all files transitively affected by a change to `changed`.
172	    pub fn affected(&self, changed: &Utf8Path) -> FxHashSet<Utf8PathBuf> {
173	        let mut visited: FxHashSet<Utf8PathBuf> = Default::default();
174	        let mut queue: VecDeque<Utf8PathBuf> = VecDeque::new();
175	        queue.push_back(changed.to_owned());
176	
177	        while let Some(file) = queue.pop_front() {
178	            if visited.insert(file.clone()) {
179	                for dep in self.inner.get(&file).into_iter().flatten() {
180	                    queue.push_back(dep.clone());
181	                }
182	            }
183	        }
184	
185	        visited
186	    }
187	}
188	
189	// ─── JSON serialization helpers ──────────────────────────────────────────────
190	
191	/// Serialize an [`ExtractionOutput`] to a JSON string.
192	///
193	/// Defined in core (not in the NAPI crate) so the JSON-building logic for
194	/// `PropType`'s hand-written `Serialize` (see ADR 0002) happens once here,
195	/// not in every downstream crate.
196	pub fn extraction_output_to_json(output: &ExtractionOutput) -> Result<String, serde_json::Error> {
197	    serde_json::to_string(output)
198	}
199	
200	/// Serialize an [`IncrementalUpdate`] to a JSON string (same reason as above).
201	pub fn incremental_update_to_json(update: &IncrementalUpdate) -> Result<String, serde_json::Error> {
202	    serde_json::to_string(update)
203	}
204	
205	// ─── Main cold extraction ─────────────────────────────────────────────────────
206	
207	/// Stateless extraction — suitable for CLI and NAPI cold runs.
208	pub fn extract(options: &PipelineOptions) -> ExtractionOutput {
209	    extract_with_global(options, false).0
210	}
211	
212	/// Shared implementation for `extract()` and `WatchSession::initialize()`.
213	/// Runs every phase (discover, parse, merge, Full-mode `@types/react`,
214	/// ambient lib.d.ts, resolve) exactly once and hands back everything a caller
215	/// might need beyond the public-facing output: the fully-merged
216	/// `GlobalSourceData` (so watch mode doesn't have to hand-rebuild a second,
217	/// easily-incomplete one just for incremental updates — see `WatchSession`'s
218	/// prior bug, where its own rebuild skipped the Full-mode/ambient-lib.d.ts
219	/// merges entirely) and each file's own parsed `SourceData` (so watch mode can
220	/// seed its per-file cache without re-parsing). `capture_source_data` is
221	/// `false` for the one-shot `extract()` path, which never looks at the third
222	/// tuple element — skip the extra per-file clone in that case.
223	pub(crate) fn extract_with_global(
224	    options: &PipelineOptions,
225	    capture_source_data: bool,
226	) -> (ExtractionOutput, Arc<GlobalSourceData>, Vec<(Utf8PathBuf, SourceData)>) {
227	    let start = Instant::now();
228	    let mut diagnostics = Vec::new();
229	
230	    // Phase 0: Validate that configured source directories exist. A typo'd --src (or a
231	    // stale docgen.config.ts srcDirs) must not silently produce an empty-but-valid-looking
232	    // result — see CLAUDE.md non-negotiable #6.
233	    let missing_src_dirs: Vec<&Utf8PathBuf> =
234	        options.src_dirs.iter().filter(|dir| !dir.as_std_path().is_dir()).collect();
235	    if options.src_dirs.is_empty() {
236	        diagnostics.push(Diagnostic {
237	            severity: DiagnosticSeverity::Error,
238	            message: "No source directories configured — src_dirs is empty".into(),
239	            file: None,
240	            line: None,
241	            column: None,
242	            help: Some("Set --src (or docgen.config.ts srcDirs) to at least one directory to scan.".into()),
243	            code: DiagnosticCode::IoError,
244	        });
245	    } else if missing_src_dirs.len() == options.src_dirs.len() {
246	        diagnostics.push(Diagnostic {
247	            severity: DiagnosticSeverity::Error,
248	            message: format!(
249	                "None of the configured source directories exist: {}",
250	                options.src_dirs.iter().map(|dir| dir.as_str()).collect::<Vec<_>>().join(", ")
251	            ),
252	            file: options.src_dirs.first().map(ToString::to_string),
253	            line: None,
254	            column: None,
255	            help: Some("Check --src (or docgen.config.ts srcDirs) for a typo'd or stale path.".into()),
256	            code: DiagnosticCode::IoError,
257	        });
258	    } else {
259	        for dir in missing_src_dirs {
260	            diagnostics.push(Diagnostic {
261	                severity: DiagnosticSeverity::Warning,
262	                message: format!("Source directory does not exist: {dir}"),
263	                file: Some(dir.to_string()),
264	                line: None,
265	                column: None,
266	                help: Some("Check --src (or docgen.config.ts srcDirs) for a typo'd or stale path.".into()),
267	                code: DiagnosticCode::IoError,
268	            });
269	        }
270	    }
271	
272	    // Load the DTS parse-result cache (silently empty if missing/stale).
273	    let cache = Arc::new(DtsCache::load_from_disk(options.cache_dir.as_deref()));
274	    let cache_ref = Arc::clone(&cache);
275	
276	    // Phase 1: Discover source files.
277	    let (src_files, mut discover_diagnostics) = discover_files(&options.src_dirs, &options.exclude_patterns);
278	    diagnostics.append(&mut discover_diagnostics);
279	    let files_parsed = src_files.len() as u32;
280	
281	    // Counter for cache hits (atomic so rayon closures can increment safely).
282	    let cache_hits = AtomicU32::new(0);
283	
284	    // Phase 2: Parallel parse with rayon — check DTS cache for .d.ts files.
285	    // The whole closure body is wrapped in `contain_panic` so one file's
286	    // parse panicking (a bug in the OXC visitor, an unanticipated AST shape)
287	    // degrades to a per-file diagnostic instead of poisoning the entire
288	    // `.collect()` and crashing the whole extraction run for every file.
289	    let source_data_vec: Vec<(Utf8PathBuf, SourceData, Option<Diagnostic>)> = src_files
290	        .par_iter()
291	        .map(|path| {
292	            let label = format!("parse:{path}");
293	            crate::panic_guard::contain_panic(&label, || {
294	                #[cfg(test)]
295	                if path.file_name() == Some(PARSE_PANIC_TEST_SENTINEL) {
296	                    panic!("simulated parse-phase panic (test-only sentinel)");
297	                }
298	
299	                let is_dts = path.as_str().ends_with(".d.ts");
300	                let (source, io_diag) = match std::fs::read_to_string(path) {
301	                    Ok(s) => (s, None),
302	                    Err(e) => (String::new(), Some(Diagnostic::io_read_error(path, &e))),
303	                };
304	                // The cache key is a content hash (see cache.rs's CacheKey doc
305	                // comment for why, vs. mtime+size), so the file must already be
306	                // read before a cache lookup can happen — this is still exactly
307	                // one read either way (hit or miss), never two.
308	                if is_dts {
309	                    if let Some(cached) = cache_ref.get(path, &source) {
310	                        cache_hits.fetch_add(1, Ordering::Relaxed);
311	                        return (path.clone(), cached, io_diag);
312	                    }
313	                }
314	                let data = crate::extractor::parse_file(path, &source);
315	                if is_dts {
316	                    cache_ref.insert(path, &source, data.clone());
317	                }
318	                (path.clone(), data, io_diag)
319	            })
320	            .unwrap_or_else(|diag| (path.clone(), SourceData::default(), Some(diag)))
321	        })
322	        .collect();
323	
324	    let dts_cache_hits = cache_hits.load(Ordering::Relaxed);
325	
326	    // Phase 3: Merge into GlobalSourceData (sequential — fast hash-map insertions).
327	    let mut global = GlobalSourceData::default();
328	    let mut per_file_data = Vec::new();
329	    for (path, mut data, io_diag) in source_data_vec {
330	        if let Some(d) = io_diag {
331	            diagnostics.push(d);
332	        }
333	        // Surface any diagnostics the extractor raised while parsing this file
334	        // (excessive nesting, syntax errors) — never drop them silently.
335	        diagnostics.append(&mut data.diagnostics);
336	        diagnostics.extend(options.plugins.run_on_file_extracted(&path, &mut data));
337	        if capture_source_data {
338	            per_file_data.push((path.clone(), data.clone()));
339	        }
340	        global.merge(&path, data);
341	    }
342	
343	    // Phase 3.5: Full HTML attribute mode needs @types/react's real interfaces
344	    // (HTMLAttributes, AriaAttributes, ButtonHTMLAttributes, etc.) merged in
345	    // before resolution runs, so the resolver can look them up like any other
346	    // interface instead of just recording an InheritedLayer. Cached the same way
347	    // as any other .d.ts — this cost is paid once per @types/react version, not
348	    // per extraction run.
349	    if options.html_attributes == HtmlAttributeMode::Full {
350	        let from_dir = canonicalize_first_src_dir(&options.src_dirs).unwrap_or_else(|| Utf8PathBuf::from("."));
351	        match crate::resolver::resolve_package_dts_path(&from_dir, "react") {
352	            Some(react_dts_path) => {
353	                let react_dts_path = Utf8PathBuf::from(react_dts_path);
354	                merge_cached_dts_file(&react_dts_path, &cache, &mut global, &mut diagnostics);
355	            }
356	            None => {
357	                diagnostics.push(Diagnostic {
358	                    severity: DiagnosticSeverity::Warning,
359	                    message: "HtmlAttributeMode::Full requested but @types/react could not be resolved".into(),
360	                    file: None,
361	                    line: None,
362	                    column: None,
363	                    help: Some("Check that @types/react is installed. Falling back to curated attributes.".into()),
364	                    code: DiagnosticCode::UnresolvableImport,
365	                });
366	            }
367	        }
368	    }
369	
370	    // Phase 3.6: TypeScript's own lib.es5.d.ts/lib.dom.d.ts declare native/DOM
371	    // ambient globals (Date, RegExp, Element, Node, ...) that never go through
372	    // an import — nothing else ever has a reason to resolve them the way an
373	    // import statement triggers @types/react above. Always attempted, not
374	    // mode-gated: a native global showing up as a bare, unexpandable Named
375	    // reference (exactly like HTMLAttributes already does) is correct for
376	    // every user in every mode. Silent no-op when `typescript` isn't reachable
377	    // (e.g. a project with no node_modules at all) — this is a best-effort
378	    // enhancement the user never opted into, so failure isn't worth a
379	    // diagnostic; the existing per-type "cannot resolve" diagnostics still
380	    // fire exactly as before in that case.
381	    if let Some(from_dir) = canonicalize_first_src_dir(&options.src_dirs) {
382	        for lib_path in crate::resolver::resolve_ts_lib_paths(&from_dir) {
383	            let lib_path = Utf8PathBuf::from(lib_path);
384	            merge_cached_dts_file(&lib_path, &cache, &mut global, &mut diagnostics);
385	        }
386	    }
387	
388	    let global = Arc::new(global);
389	
390	    // Phase 4: Resolve all components in parallel.
391	    // Borrowed, not cloned: `resolve_component` already takes `&ComponentMapping`,
392	    // and the parallel `.par_iter()` below only ever produces borrows anyway —
393	    // cloning here just to immediately re-borrow deep-cloned every mapping's
394	    // Strings/Vecs/param_defaults map for no reason, once per component.
395	    let mappings: Vec<&ComponentMapping> = global
396	        .component_mappings
397	        .iter()
398	        .filter(|m| !should_skip(&m.component_name, &options.exclude_prefixes))
399	        .collect();
400	
401	    // The whole closure body is wrapped in `contain_panic` so one component's
402	    // resolution panicking degrades to a per-component diagnostic instead of
403	    // poisoning the entire `.collect()` and crashing the whole extraction
404	    // run for every component.
405	    let ctx = Arc::new(ResolutionContext::new(global.clone(), options));
406	    let results: Vec<(ComponentEntry, Vec<Diagnostic>)> = mappings
407	        .par_iter()
408	        .copied()
409	        .map(|mapping| {
410	            let label = format!("resolve:{}", mapping.component_name);
411	            crate::panic_guard::contain_panic(&label, || {
412	                #[cfg(test)]
413	                if mapping.component_name == RESOLVE_PANIC_TEST_SENTINEL {
414	                    panic!("simulated resolve-phase panic (test-only sentinel)");
415	                }
416	
417	                resolve_component(mapping, &ctx)
418	            })
419	            .unwrap_or_else(|diag| {
420	                let stub = ComponentEntry {
421	                    display_name: mapping.component_name.clone(),
422	                    file_path: mapping.file_path.clone(),
423	                    description: String::new(),
424	                    props: Default::default(),
425	                    inheritance: vec![],
426	                    notable_inherited: Default::default(),
427	                    discriminant_prop: None,
428	                    composes: vec![],
429	                    tags: Default::default(),
430	                    methods: vec![],
431	                };
432	                (stub, vec![diag])
433	            })
434	        })
435	        .collect();
436	
437	    // Phase 5: Collect output.
438	    let mut components = std::collections::BTreeMap::new();
439	    let mut seen_names: std::collections::HashMap<String, u32> = Default::default();
440	
441	    for (entry, diags) in results {
442	        let base_name = entry.display_name.clone();
443	        let count = seen_names.entry(base_name.clone()).or_insert(0);
444	        *count += 1;
445	
446	        let key = if *count == 1 {
447	            base_name
448	        } else {
449	            // File stem alone isn't unique across different src_dirs — two
450	            // different libraries each shipping a same-named file (e.g.
451	            // "Button.tsx" in one directory and "Button.d.ts" in another,
452	            // ubiquitous across real component libraries) produced the
453	            // identical disambiguated key too, silently overwriting one
454	            // another in `components` with zero diagnostic. The full file
455	            // path is always unique per file, so it can't repeat this failure
456	            // mode for distinct files (only a genuine duplicate declaration of
457	            // the same name in the very same file would still collide, a
458	            // materially different and much rarer situation).
459	            format!("{} ({})", base_name, entry.file_path)
460	        };
461	
462	        let mut entry = entry;
463	        diagnostics.extend(options.plugins.run_on_component_resolved(&mut entry));
464	        // Capture the cheap Utf8PathBuf clone before `entry` moves into
465	        // `insert` — the alternative (`entry.clone()`) deep-clones the whole
466	        // resolved ComponentEntry (props map, inheritance chain, tags, ...)
467	        // on every component just to keep `file_path` readable for a
468	        // diagnostic that only fires on the rare collision case.
469	        let new_file_path = entry.file_path.clone();
470	        if let Some(previous) = components.insert(key.clone(), entry) {
471	            diagnostics.push(Diagnostic {
472	                severity: DiagnosticSeverity::Warning,
473	                message: format!(
474	                    "Duplicate component key '{key}' — colliding file paths: previously '{}', now '{}'",
475	                    previous.file_path, new_file_path
476	                ),
477	                file: Some(new_file_path.to_string()),
478	                line: None,
479	                column: None,
480	                help: Some(
481	                    "Two resolved components produced the same display name and disambiguation key — only \
482	                     the later one is kept in the output. Check for overlapping src_dirs or a genuine \
483	                     duplicate declaration."
484	                        .into(),
485	                ),
486	                code: DiagnosticCode::ComponentKeyCollision,
487	            });
488	        }
489	        diagnostics.extend(diags);
490	    }
491	
492	    let enums = collect_public_enums(&global);
493	
494	    // Persist cache for the next run.
495	    // Arc::try_unwrap succeeds because all rayon workers have finished; fallback
496	    // calls save_to_disk via the Arc deref since DtsCache::save_to_disk takes &self.
497	    let cache_save_diagnostic = match Arc::try_unwrap(cache) {
498	        Ok(c) => c.save_to_disk(),
499	        Err(arc) => arc.save_to_disk(),
500	    };
501	    diagnostics.extend(cache_save_diagnostic);
502	
503	    let duration_ms = start.elapsed().as_millis() as u64;
504	    let components_extracted = components.len() as u32;
505	
506	    let output = ExtractionOutput {
507	        components,
508	        enums,
509	        diagnostics,
510	        stats: ExtractionStats {
511	            components_extracted,
512	            files_parsed,
513	            dts_cache_hits,
514	            duration_ms,
515	            ..Default::default()
516	        },
517	    };
518	    (output, global, per_file_data)
519	}
520	
521	// ─── Helper functions ─────────────────────────────────────────────────────────
522	
523	/// Parse-or-load-from-cache a single `.d.ts` file and merge it into `global`,
524	/// draining any diagnostics the parse produced into `diagnostics` first —
525	/// matching how the main per-project-file loop (Phase 3) already handles this.
526	/// Shared by the Full-mode `@types/react` merge (Phase 3.5) and the ambient
527	/// `lib.d.ts` merge (Phase 3.6), which previously each merged the parsed data
528	/// directly with no diagnostics drain at all: an excessive-nesting trip or a
529	/// parse error while parsing either file would have been silently discarded,
530	/// since `GlobalSourceData` itself has no diagnostics field to catch it later.
531	fn merge_cached_dts_file(
532	    path: &Utf8Path,
533	    cache: &DtsCache,
534	    global: &mut GlobalSourceData,
535	    diagnostics: &mut Vec<Diagnostic>,
536	) {
537	    let source = std::fs::read_to_string(path).unwrap_or_default();
538	    let mut data = match cache.get(path, &source) {
539	        Some(cached) => cached,
540	        None => {
541	            let data = crate::extractor::parse_file(path, &source);
542	            cache.insert(path, &source, data.clone());
543	            data
544	        }
545	    };
546	    diagnostics.append(&mut data.diagnostics);
547	    global.merge(path, data);
548	}
549	
550	/// Canonicalize `src_dirs`' first entry to use as the "from" directory for
551	/// resolving @types/react and TypeScript's own lib.d.ts files — must match
552	/// what discovered file paths look like (always absolute — the `ignore`
553	/// walker absolutizes them regardless of whether --src was given as relative
554	/// or absolute), since the resolver looks this same specifier up again
555	/// per-component relative to each file's own absolute directory. A relative
556	/// src_dirs entry has too few path components for oxc_resolver's ancestor
557	/// walk to ever reach the real node_modules tree, so it silently finds
558	/// nothing instead of the intended real package.
559	fn canonicalize_first_src_dir(src_dirs: &[Utf8PathBuf]) -> Option<Utf8PathBuf> {
560	    src_dirs.first().and_then(|dir| std::fs::canonicalize(dir).ok()).and_then(|p| Utf8PathBuf::from_path_buf(p).ok())
561	}
562	
563	/// Collect enum entries that are exported from their source files.
564	fn collect_public_enums(global: &GlobalSourceData) -> std::collections::BTreeMap<String, Vec<EnumEntry>> {
565	    let mut result = std::collections::BTreeMap::new();
566	
567	    for (scoped_key, entries) in &global.enums {
568	        // scoped_key = "{file_path}:{name}"
569	        if let Some((file_path_str, name)) = scoped_key.split_once(':') {
570	            let file_path = Utf8Path::new(file_path_str);
571	            let is_exported = global
572	                .re_export_map
573	                .get(file_path)
574	                .map(|exports| {
575	                    exports.iter().any(|e| match e {
576	                        LexedExport::LocalDeclaration { name: n, .. } => n == name,
577	                        _ => false,
578	                    })
579	                })
580	                .unwrap_or(false);
581	
582	            if is_exported {
583	                result.insert(name.to_owned(), entries.clone());
584	            }
585	        }
586	    }
587	
588	    result
589	}
590	
591	// ─── Tests ────────────────────────────────────────────────────────────────────
592	
593	#[cfg(test)]
594	mod tests {
595	    use super::*;
596	    use std::fs;
597	    use tempfile::TempDir;
598	
599	    #[test]
600	    fn merge_cached_dts_file_does_not_drop_parse_diagnostics() {
601	        // Adversarial review finding: Phase 3.5 (@types/react Full-mode merge)
602	        // and Phase 3.6 (ambient lib.d.ts merge) each called global.merge()
603	        // directly on freshly-parsed data with no diagnostics drain first —
604	        // GlobalSourceData has no diagnostics field, so anything the extractor
605	        // flagged while parsing either file (an excessive-nesting trip, a
606	        // parse error) was silently lost. Mirrors
607	        // extractor::tests::test_excessive_nesting_guard's exact repro shape.
608	        let tmp = TempDir::new().unwrap();
609	        let nested = "(".repeat(2500) + &")".repeat(2500);
610	        let source = format!("const x = {nested};");
611	        let path = write_file(&tmp, "lib.d.ts", &source);
612	
613	        let cache_dir = Utf8PathBuf::from_path_buf(tmp.path().join("cache")).unwrap();
614	        let cache = DtsCache::load_from_disk(Some(&cache_dir));
615	        let mut global = GlobalSourceData::default();
616	        let mut diagnostics = Vec::new();
617	
618	        merge_cached_dts_file(&path, &cache, &mut global, &mut diagnostics);
619	
620	        assert!(
621	            diagnostics.iter().any(|d| d.code == DiagnosticCode::ExcessiveNesting),
622	            "expected the excessive-nesting diagnostic to survive the merge, got {:?}",
623	            diagnostics
624	        );
625	    }
626	
627	    /// Write a file into a temp dir and return its Utf8PathBuf.
628	    fn write_file(dir: &TempDir, name: &str, content: &str) -> Utf8PathBuf {
629	        let path = dir.path().join(name);
630	        fs::write(&path, content).unwrap();
631	        Utf8PathBuf::from_path_buf(path).unwrap()
632	    }
633	
634	    // ── a_panic_during_parse_phase_degrades_to_a_diagnostic_not_a_crash ──────
635	    //
636	    // No plugin system exists in this codebase yet to inject a panic via a
637	    // hook (that's a separate, later task), so this drives the real Phase 2
638	    // rayon closure via the sentinel filename it checks for under
639	    // `#[cfg(test)]` (see the `PARSE_PANIC_TEST_SENTINEL` check above).
640	
641	    #[test]
642	    fn a_panic_during_parse_phase_degrades_to_a_diagnostic_not_a_crash() {
643	        let tmp = TempDir::new().unwrap();
644	        write_file(&tmp, "Button.tsx", "export const Button = () => null;");
645	        write_file(&tmp, PARSE_PANIC_TEST_SENTINEL, "export const Other = () => null;");
646	
647	        let options = PipelineOptions {
648	            src_dirs: vec![Utf8PathBuf::from_path_buf(tmp.path().to_owned()).unwrap()],
649	            cache_dir: Some(Utf8PathBuf::from_path_buf(tmp.path().join("cache")).unwrap()),
650	            ..Default::default()
651	        };
652	
653	        // Must not panic the test process — that's the whole point.
654	        let output = extract(&options);
655	
656	        assert_eq!(output.stats.files_parsed, 2, "both files should still be counted as discovered");
657	        assert!(
658	            output.diagnostics.iter().any(|d| d.code == DiagnosticCode::InternalPanic),
659	            "expected an InternalPanic diagnostic, got {:?}",
660	            output.diagnostics
661	        );
662	    }
663	
664	    // ── a_panic_during_resolve_phase_degrades_to_a_diagnostic_not_a_crash ────
665	    //
666	    // Same rationale as the parse-phase test above: `resolve_component` can't
667	    // be made to panic without editing non-test resolver code, so this drives
668	    // the real Phase 4 rayon closure via the sentinel component name it
669	    // checks for under `#[cfg(test)]`.
670	
671	    #[test]
672	    fn a_panic_during_resolve_phase_degrades_to_a_diagnostic_not_a_crash() {
673	        let tmp = TempDir::new().unwrap();
674	        write_file(&tmp, "Button.tsx", "export function Button(props: { label: string }) { return null; }\n");
675	        write_file(
676	            &tmp,
677	            "Other.tsx",
678	            &format!("export function {RESOLVE_PANIC_TEST_SENTINEL}(props: {{ label: string }}) {{ return null; }}\n"),
679	        );
680	
681	        let options = PipelineOptions {
682	            src_dirs: vec![Utf8PathBuf::from_path_buf(tmp.path().to_owned()).unwrap()],
683	            cache_dir: Some(Utf8PathBuf::from_path_buf(tmp.path().join("cache")).unwrap()),
684	            ..Default::default()
685	        };
686	
687	        // Must not panic the test process — that's the whole point.
688	        let output = extract(&options);
689	
690	        assert!(
691	            output.components.contains_key("Button"),
692	            "the component whose sibling panicked during resolution should still be extracted"
693	        );
694	        assert!(
695	            output.diagnostics.iter().any(|d| d.code == DiagnosticCode::InternalPanic),
696	            "expected an InternalPanic diagnostic, got {:?}",
697	            output.diagnostics
698	        );
699	    }
700

