        file_path: Utf8PathBuf,
    },
    Pick {
        base: CollectedType,
        picked_keys: Vec<std::string::String>,
        file_path: Utf8PathBuf,
    },
    Partial {
        base: CollectedType,
        file_path: Utf8PathBuf,
    },
    Required {
        base: CollectedType,
        file_path: Utf8PathBuf,
    },
    Union {
        members: Vec<CollectedType>,
        file_path: Utf8PathBuf,
    },
    Intersection {
        members: Vec<CollectedType>,
        file_path: Utf8PathBuf,
    },
    LiteralUnion {
        members: Vec<std::string::String>,
        file_path: Utf8PathBuf,
    },
    /// e.g. type Size = SomeOtherType — transparent alias
    Passthrough {
        target: CollectedType,
        file_path: Utf8PathBuf,
    },
