            }
            "Readonly" if !type_args.is_empty() && !type_args[0].contains('<') => {
                let base = CollectedType::Named { name: type_args[0].as_str().into(), args: vec![] };
                Some(CollectedTypeAlias::Passthrough { target: base, file_path: consuming_file.to_owned() })
            }
