1	use miette::{IntoDiagnostic, Result, WrapErr};
2	
3	use crate::config::{build_options, BuildOptionsArgs};
4	use crate::output::{print_diagnostics, print_summary, write_atomic};
5	
6	/// Returns the process exit code (0 = success, 2 = extraction reported an
7	/// error-severity diagnostic) rather than calling `std::process::exit`
8	/// directly — keeps the exit decision testable and lets `main()` be the only
9	/// place that actually terminates the process.
10	pub fn cmd_extract(args: crate::ExtractArgs, quiet: bool, config_path: Option<&str>) -> Result<i32> {
11	    use indicatif::{ProgressBar, ProgressStyle};
12	
13	    let html_attributes = args.html_attributes.map(|m| match m {
14	        crate::HtmlAttributeModeArg::Curated => "curated",
15	        crate::HtmlAttributeModeArg::Full => "full",
16	        crate::HtmlAttributeModeArg::None => "none",
17	    });
18	    let options = build_options(BuildOptionsArgs {
19	        src: &args.src,
20	        no_cross_package: args.no_cross_package,
21	        react_version: args.react_version.as_deref(),
22	        cache_dir: args.cache_dir.as_deref(),
23	        html_attributes,
24	        config_path,
25	        extra_builtins: &args.extra_builtins,
26	    })?;
27	
28	    let pb = if !quiet && !args.json {
29	        let pb = ProgressBar::new_spinner();
30	        pb.set_style(ProgressStyle::default_spinner().template("{spinner:.cyan} {msg}").into_diagnostic()?);
31	        pb.set_message("Extracting...");
32	        pb.enable_steady_tick(std::time::Duration::from_millis(80));
33	        Some(pb)
34	    } else {
35	        None
36	    };
37	
38	    let output = oxc_react_docgen_core::pipeline::extract(&options);
39	
40	    if let Some(pb) = pb {
41	        pb.finish_and_clear();
42	    }
43	
44	    // --json ignores --out/--format — see ExtractArgs::json's doc comment.
45	    if args.json {
46	        println!("{}", serde_json::to_string(&output).into_diagnostic()?);
47	    } else {
48	        if !quiet {
49	            print_summary(&output, quiet);
50	            print_diagnostics(&output.diagnostics);
51	        }
52	
53	        let json = match args.format {
54	            crate::OutputFormat::Canonical => serde_json::to_string_pretty(&output).into_diagnostic()?,
55	            crate::OutputFormat::Rdt => serialize_rdt(&output),
56	            crate::OutputFormat::Storybook => serialize_storybook(&output),
57	            crate::OutputFormat::Toon => oxc_react_docgen_core::toon::render_output_toon(&output),
58	        };
59	
60	        match args.out {
61	            Some(ref path) => write_atomic(path, &json).into_diagnostic().wrap_err(format!("Writing to {path}"))?,
62	            None => println!("{json}"),
63	        }
64	    }
65	
66	    // Must run regardless of --json — this is the one thing CI actually
67	    // depends on the exit code for.
68	    Ok(output.exit_code(false))
69	}
70	
71	/// RDT's type-name convention for literal unions: `{"name": "enum", "value": [...]}`
72	/// instead of inlining the literal text into `type.name` as a plain string. Lets
73	/// prop-table renderers that pattern-match `type.name === "enum"` (a common
74	/// Storybook addon integration point) show a `<select>` control for the most
75	/// common, most curated props in any design system (variant, size, color…).
76	fn rdt_type_json(prop_type: &oxc_react_docgen_core::types::PropType) -> serde_json::Value {
77	    use oxc_react_docgen_core::types::PropType;
78	
79	    if prop_type.is_literal_union() {
80	        let values: Vec<serde_json::Value> = match prop_type {
81	            PropType::Union(members) => members.iter().map(|m| serde_json::json!({"value": m.raw_string()})).collect(),
82	            PropType::LiteralUnion { members, .. } => {
83	                members.iter().map(|m| serde_json::json!({"value": format!("\"{m}\"")})).collect()
84	            }
85	            _ => vec![],
86	        };
87	        return serde_json::json!({ "name": "enum", "value": values });
88	    }
89	    serde_json::json!({ "name": prop_type.raw_string() })
90	}
91	
92	/// `methods` is always `[]` — this tool doesn't extract class methods, and RDT
93	/// consumers (Storybook's docgen addon) only ever read it for class components.
94	pub fn serialize_rdt(output: &oxc_react_docgen_core::types::ExtractionOutput) -> String {
95	    let mut map = serde_json::Map::new();
96	    for (name, entry) in &output.components {
97	        let props: serde_json::Map<String, serde_json::Value> = entry
98	            .props
99	            .iter()
100	            .map(|(k, prop)| {
101	                let obj = serde_json::json!({
102	                    "name": prop.name,
103	                    "type": rdt_type_json(&prop.prop_type),
104	                    "required": prop.required,
105	                    "defaultValue": prop.default_value.as_ref().map(|d| serde_json::json!({"value": d.value, "computed": d.computed})),
106	                    "description": prop.description,
107	                    "parent": prop.parent.as_ref().map(|p| serde_json::json!({"name": p.name, "fileName": p.file_name})),
108	                });
109	                (k.clone(), obj)
110	            })
111	            .collect();
112	        map.insert(
113	            name.clone(),
114	            serde_json::json!({
115	                "displayName": entry.display_name,
116	                "props": serde_json::Value::Object(props),
117	                "description": entry.description,
118	                "methods": [],
119	                "tags": entry.tags,
120	                "composes": entry.composes,
121	            }),
122	        );
123	    }
124	    serde_json::to_string_pretty(&serde_json::Value::Object(map)).unwrap_or_default()
125	}
126	
127	pub fn serialize_storybook(output: &oxc_react_docgen_core::types::ExtractionOutput) -> String {
128	    let mut map = serde_json::Map::new();
129	    for (name, entry) in &output.components {
130	        let props: serde_json::Map<String, serde_json::Value> = entry
131	            .props
132	            .iter()
133	            .map(|(k, prop)| {
134	                let obj = serde_json::json!({
135	                    "name": prop.name,
136	                    "type": { "name": prop.prop_type.raw_string() },
137	                    "required": prop.required,
138	                    "defaultValue": prop.default_value.as_ref().map(|d| serde_json::json!({"value": d.value})),
139	                    "description": prop.description,
140	                });
141	                (k.clone(), obj)
142	            })
143	            .collect();
144	        map.insert(
145	            name.clone(),
146	            serde_json::json!({
147	                "displayName": entry.display_name,
148	                "props": serde_json::Value::Object(props),
149	                "description": entry.description,
150	                "methods": [],
151	            }),
152	        );
153	    }
154	    serde_json::to_string_pretty(&serde_json::Value::Object(map)).unwrap_or_default()
155	}
