158	mod tests {
159	    use super::*;
160	
161	    fn args_for(src: &str, json: bool) -> crate::ExtractArgs {
162	        crate::ExtractArgs {
163	            src: vec![src.to_owned()],
164	            out: None,
165	            format: crate::OutputFormat::Canonical,
166	            no_cross_package: false,
167	            react_version: None,
168	            cache_dir: None,
169	            html_attributes: None,
170	            extra_builtins: vec![],
171	            json,
172	        }
173	    }
174	
175	    #[test]
176	    fn json_mode_still_returns_the_error_exit_code() {
177	        // Adversarial review finding: --json returned before the error-
178	        // diagnostic exit-code check, so `extract --json` always exited 0
179	        // even on hard errors — the one signal CI actually depends on.
180	        let code = cmd_extract(args_for("/nonexistent/does-not-exist", true), true, None)
181	            .expect("cmd_extract itself should not error");
182	        assert_eq!(code, 2, "expected exit code 2 for a nonexistent src dir even in --json mode");
183	    }
184	
185	    #[test]
186	    fn non_json_mode_returns_the_same_error_exit_code() {
187	        // Same check, non-json path — both must agree.
188	        let code = cmd_extract(args_for("/nonexistent/does-not-exist", false), true, None)
189	            .expect("cmd_extract itself should not error");
190	        assert_eq!(code, 2);
191	    }
192	
193	    // ── SPEC-CLI-001a AC-001: extract against a source directory that
194	    // produces zero Error-severity diagnostics returns exit code 0.
195	
196	    #[test]
197	    fn clean_run_returns_exit_code_zero() {
198	        let manifest_dir = camino::Utf8Path::new(env!("CARGO_MANIFEST_DIR"));
199	        let tmp = tempfile::TempDir::new_in(manifest_dir).unwrap();
200	        std::fs::write(
201	            tmp.path().join("Widget.tsx"),
202	            "export function Widget(props: { label: string }) { return null; }\n",
203	        )
204	        .unwrap();
205	        let code = cmd_extract(args_for(tmp.path().to_str().unwrap(), true), true, None)
206	            .expect("cmd_extract should not error");
207	        assert_eq!(code, 0, "expected exit code 0 for a clean run");
208	    }
209	
210	    // ── SPEC-CLI-001b AC-002/AC-003/AC-004: extract --out's actual call site,
211	    // not just write_atomic in isolation — these previously had zero coverage;
212	    // a regression reverting extract.rs's --out handling to a bare
213	    // std::fs::write would have passed every existing test in the suite.
214	
215	    #[test]
216	    fn extract_out_writes_valid_output_with_no_leftover_temp_file() {
217	        let manifest_dir = camino::Utf8Path::new(env!("CARGO_MANIFEST_DIR"));
218	        let tmp = tempfile::TempDir::new_in(manifest_dir).unwrap();
219	        std::fs::write(
220	            tmp.path().join("Widget.tsx"),
221	            "export function Widget(props: { label: string }) { return null; }\n",
222	        )
223	        .unwrap();
224	
225	        let out_path = tmp.path().join("out.json");
226	        let mut args = args_for(tmp.path().to_str().unwrap(), false);
227	        args.out = Some(out_path.to_str().unwrap().to_owned());
228	
229	        let code = cmd_extract(args, true, None).expect("cmd_extract should succeed");
230	        assert_eq!(code, 0);
231	
232	        let contents = std::fs::read_to_string(&out_path).expect("expected the --out file to exist");
233	        let parsed: serde_json::Value = serde_json::from_str(&contents).expect("--out file should be valid JSON");
234	        assert!(
235	            parsed["components"]["Widget"].is_object(),
236	            "expected the Widget component in the --out file, got {contents}"
237	        );
238	
239	        let tmp_file = tmp.path().join(".out.json.tmp");
240	        assert!(!tmp_file.exists(), "no leftover temp file should remain after a successful --out write");
241	    }
242	
243	    // The test above alone can't distinguish write_atomic from a naive
244	    // std::fs::write — both produce identical end states for a plain path
245	    // (verified: reverting extract.rs's --out arm to bare std::fs::write
246	    // still passed it). A symlinked --out target can distinguish them: a
247	    // rename-based write REPLACES the symlink itself with a real file at
248	    // PATH, while a naive write FOLLOWS the symlink and corrupts whatever
249	    // it points to instead — the one observable difference a black-box
250	    // test can exploit without instrumenting the write mid-flight.
251	
252	    #[cfg(unix)]
